import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c}from"./app-FtcyK8lR.js";var l=JSON.parse(`{"path":"/api/management.html","title":"管理员会话、编辑区与发布 API","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1793083391000,"contributors":[{"name":"之旸 刘","username":"","email":"marufyurisa@outlook.com","commits":3}],"changelog":[{"hash":"a7bc7e5f74740c184e03fa5817e5e4576113490b","time":1793083391000,"email":"marufyurisa@outlook.com","author":"之旸 刘","message":"feat: integrate release workflows, managed backups and runtime fixes"},{"hash":"c9aefe52adfa8a8ee7b6f76be57885cf3eed176b","time":1792728460000,"email":"marufyurisa@outlook.com","author":"之旸 刘","message":"feat: consolidate config edit protection and spectrum refinements"},{"hash":"19811119f54f6a4d04aa76de9c6478413b9ca6ca","time":1792568191000,"email":"marufyurisa@outlook.com","author":"之旸 刘","message":"docs: rewrite fork API reference for published configurations and admin sessions"}]},"filePathRelative":"api/management.md"}`),u={name:`management.md`};function d(c,l,u,d,f,p){let m=t(`RouteLink`);return s(),o(`div`,null,[l[3]||=i(`h1`,{id:`管理员会话、编辑区与发布-api`,tabindex:`-1`},[i(`a`,{class:`header-anchor`,href:`#管理员会话、编辑区与发布-api`},`#`),e(` 管理员会话、编辑区与发布 API`)],-1),i(`p`,null,[a(m,{to:`/api/`},{default:r(()=>[...l[0]||=[e(`返回 API 入口`,-1)]]),_:1}),l[2]||=e(` · `,-1),a(m,{to:`/api/runtime.html`},{default:r(()=>[...l[1]||=[e(`业务运行时读取`,-1)]]),_:1})]),l[4]||=n(`<p>所有路径相对于实际部署地址。管理 API 面向控制台或管理工具；业务应用读取发布配置使用公开运行时接口，不需要拿管理员密码登录。</p><h2 id="_1-登录和会话" tabindex="-1"><a class="header-anchor" href="#_1-登录和会话">#</a> 1. 登录和会话</h2><h3 id="登录" tabindex="-1"><a class="header-anchor" href="#登录">#</a> 登录</h3><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">POST /api/v1/auth/login</span>
<span class="line"><span class="token header"><span class="token header-name keyword">Origin</span><span class="token punctuation">:</span> <span class="token header-value">http://127.0.0.1:18080</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">Content-Type</span><span class="token punctuation">:</span> <span class="token header-value">application/json</span></span></span>
<span class="line"><span class="token application-json"></span>
<span class="line"><span class="token punctuation">{</span><span class="token property">&quot;username&quot;</span><span class="token operator">:</span><span class="token string">&quot;admin&quot;</span><span class="token punctuation">,</span><span class="token property">&quot;password&quot;</span><span class="token operator">:</span><span class="token string">&quot;&lt;管理员密码&gt;&quot;</span><span class="token punctuation">}</span></span>
<span class="line"></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Origin 只有协议、主机、端口，不含 <code>/rainbow-bridge</code>，必须在部署的 trusted_origins 中精确匹配；登录缺少 Origin 也会被拒绝。不要把示例密码占位符当真实密码。</p><p>成功 HTTP 200，服务端 Set-Cookie，并返回：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;msg&quot;</span><span class="token operator">:</span> <span class="token string">&quot;success&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;user&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token property">&quot;id&quot;</span><span class="token operator">:</span><span class="token string">&quot;1&quot;</span><span class="token punctuation">,</span><span class="token property">&quot;username&quot;</span><span class="token operator">:</span><span class="token string">&quot;admin&quot;</span><span class="token punctuation">,</span><span class="token property">&quot;role&quot;</span><span class="token operator">:</span><span class="token string">&quot;admin&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;session&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">&quot;expires_at&quot;</span><span class="token operator">:</span><span class="token string">&quot;2026-10-21T10:00:00Z&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;idle_expires_at&quot;</span><span class="token operator">:</span><span class="token string">&quot;2026-10-21T04:00:00Z&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;csrf_token&quot;</span><span class="token operator">:</span><span class="token string">&quot;&lt;本次会话的令牌&gt;&quot;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Cookie 为 HttpOnly、SameSite=Lax，名称和 Secure 由部署配置决定，Path 对应 BasePath；不要把开发 Cookie 名硬编码为所有部署值。服务端默认空闲期限 2 小时、绝对期限 8 小时，配置可调整；成功管理访问会续空闲期限，但不越过绝对期限。公开运行时读取不续管理员会话。</p><p>浏览器使用真实 Cookie jar；同源请求自动携带 Cookie，跨源 fetch 需 <code>credentials: &#39;include&#39;</code>，还必须符合服务端精确来源 CORS、Cookie 域/路径及 SameSite/Secure 规则。不同来源不代表任意跨站点都能使用会话。</p><p>CSRF 只在内存保存，不写 URL、日志或持久化存储。管理员写请求使用 Cookie，并附 <code>X-CSRF-Token</code> 和可信 Origin；有 Origin 的管理读请求也校验来源。无 Origin 的非浏览器管理请求仍需有效 Cookie，写操作仍需 CSRF。旧 Bearer、自报角色或用户请求头不能替代会话。</p><h3 id="会话接口" tabindex="-1"><a class="header-anchor" href="#会话接口">#</a> 会话接口</h3><table><thead><tr><th>方法与路径</th><th>输入</th><th>成功 data / 行为</th></tr></thead><tbody><tr><td>GET <code>/api/v1/auth/me</code></td><td>会话 Cookie</td><td>同登录 data；恢复页面会话与 CSRF</td></tr><tr><td>POST <code>/api/v1/auth/logout</code></td><td>Cookie、CSRF、空体或 <code>{}</code></td><td><code>{&quot;logged_out&quot;:true}</code>，撤销会话并清 Cookie；无有效会话可幂等退出</td></tr><tr><td>POST <code>/api/v1/auth/password</code></td><td>Cookie、CSRF、JSON 的 current_password/new_password</td><td><code>{&quot;reauth_required&quot;:true}</code>，修改后撤销全部会话，重新登录</td></tr></tbody></table><p>登录/改密仅接受 JSON，请求体上限 4 KiB，拒绝未知 JSON 字段。auth 成功正文 code=0，错误为实际 HTTP 状态及 <code>{code,msg,error_type}</code>。其他管理模块成功通常为 code=200，不要直接复用“code 必须等于 0”的判定。</p><table><thead><tr><th>HTTP</th><th>error_type</th><th>含义</th></tr></thead><tbody><tr><td>400</td><td>AUTH_INVALID_REQUEST / AUTH_CURRENT_PASSWORD_INVALID</td><td>参数不合法 / 当前密码错误</td></tr><tr><td>401</td><td>AUTH_INVALID_CREDENTIALS / AUTH_REQUIRED</td><td>凭据错误 / 需要登录</td></tr><tr><td>403</td><td>AUTH_FORBIDDEN / AUTH_CSRF_INVALID / AUTH_ORIGIN_DENIED</td><td>权限、CSRF 或来源失败</td></tr><tr><td>409</td><td>AUTH_CREDENTIAL_CHANGED</td><td>校验期间凭据变化，重新登录</td></tr><tr><td>413 / 415</td><td>AUTH_INVALID_REQUEST</td><td>请求体过大 / Content-Type 不受支持</td></tr><tr><td>429</td><td>AUTH_RATE_LIMITED</td><td>登录限流，遵守 Retry-After</td></tr><tr><td>503</td><td>AUTH_BUSY / AUTH_UNAVAILABLE</td><td>密码计算繁忙 / 认证不可用</td></tr></tbody></table><p>当前是简单管理员会话，不提供账号注册、多角色管理或完整 IAM 平台。未来外部 IAM 接入不在本合同中承诺。</p><h2 id="_2-编辑区请求结构" tabindex="-1"><a class="header-anchor" href="#_2-编辑区请求结构">#</a> 2. 编辑区请求结构</h2><p>编辑区与已发布版本独立；修改编辑区后需要重新锁版、创建版本并切换生效。锁版时配置写入、资源上传及相应范围变更会被阻止；读取和导出不因此停止。</p><p>配置列表：<code>GET /api/v1/config/list?environment_key=default&amp;pipeline_key=default</code>，成功 data 为 <code>{total,list}</code>，不是旧文档里的 configs。单项详情 data 为 <code>{config}</code>。</p><p>配置创建请求：</p><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">POST /api/v1/config/create</span>
<span class="line"><span class="token header"><span class="token header-name keyword">Content-Type</span><span class="token punctuation">:</span> <span class="token header-value">application/json</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">X-CSRF-Token</span><span class="token punctuation">:</span> <span class="token header-value">&lt;当前会话令牌&gt;</span></span></span>
<span class="line"><span class="token application-json"></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;config&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;alias&quot;</span><span class="token operator">:</span><span class="token string">&quot;welcome&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;name&quot;</span><span class="token operator">:</span><span class="token string">&quot;欢迎语&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;type&quot;</span><span class="token operator">:</span><span class="token string">&quot;text&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;content&quot;</span><span class="token operator">:</span><span class="token string">&quot;你好&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;description&quot;</span><span class="token operator">:</span><span class="token string">&quot;&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;remark&quot;</span><span class="token operator">:</span><span class="token string">&quot;&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;is_perm&quot;</span><span class="token operator">:</span><span class="token boolean">false</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>alias 创建后不可改，name 可改；content 在管理请求中是字符串，object/keyvalue 需传编码后的 JSON 字符串。配置删除直接传 environment_key、pipeline_key、resource_key，不套 config。</p><p>环境 create/update 使用 <code>{&quot;environment&quot;:{...}}</code>，字段含 environment_key、environment_name、description、sort_order、is_active。渠道 create/update 使用顶层 environment_key 与 <code>pipeline</code> 对象，内含 environment_key、pipeline_key、pipeline_name、description、sort_order、is_active。列表成功 data 为 <code>{total,list}</code>，详情为 <code>{environment}</code> 或 <code>{pipeline}</code>。</p><p>资源上传使用 multipart/form-data 的 file、environment_key、pipeline_key；不要手动给 FormData 设置缺少 boundary 的 Content-Type。成功 data 为 <code>{asset,reference}</code>，reference 是 <code>asset://&lt;file_id&gt;</code>，应使用返回值，不靠原始资源路径猜 ID。资源下载使用实际返回的 url（可能包含部署前缀及文件名）。跨范围引用会被锁版检查拒绝；迁移配置应走迁移接口并核对资源结果，不能只复制另一范围的 URL。</p><p>迁移/归档与发布静态包不同。迁移 JSON 字段是 source_environment_key、source_pipeline_key、target_environment_key、target_pipeline_key、resource_keys、overwrite；不是 source_environment 等旧文档字段。选择性导出入口实际为 <code>POST /api/v1/transfer/export</code>，JSON 包含 format 与 selections（范围和 resource_keys）；不能按内部方法名推测出另一个路径或改成 GET。完整路由见入口索引及 IDL。导入成功后还要核对 data.resource_import 和逐项问题，不能仅凭 HTTP 200 判断全部资源恢复。</p><p>部分历史 CRUD 的业务错误仍通过 HTTP 200 + 非 200 正文 code 返回，认证/冻结错误则会使用真实 HTTP 状态。此处只记录兼容现状，不声称本轮已统一历史错误协议。</p><h3 id="配置编辑冲突保护" tabindex="-1"><a class="header-anchor" href="#配置编辑冲突保护">#</a> 配置编辑冲突保护</h3><p>打开编辑时调用 <code>GET /api/v1/config/detail?environment_key=default&amp;pipeline_key=default&amp;resource_key=&lt;配置键&gt;</code>。详情直接读取数据库，返回 <code>Cache-Control: no-store</code>。列表、详情、创建及修改成功的配置均包含服务端生成的 <code>edit_revision</code>（小写标准 UUID v4）。</p><p>普通修改须原样回传打开时的标识，位于请求顶层：</p><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">POST /api/v1/config/update</span>
<span class="line"><span class="token header"><span class="token header-name keyword">Content-Type</span><span class="token punctuation">:</span> <span class="token header-value">application/json</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">X-CSRF-Token</span><span class="token punctuation">:</span> <span class="token header-value">&lt;当前会话令牌&gt;</span></span></span>
<span class="line"><span class="token application-json"></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;expected_edit_revision&quot;</span><span class="token operator">:</span><span class="token string">&quot;c29c6fbc-a274-4b88-8a21-a1e7cc51ba83&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;config&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;resource_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;&lt;配置键&gt;&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;name&quot;</span><span class="token operator">:</span><span class="token string">&quot;欢迎语&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;type&quot;</span><span class="token operator">:</span><span class="token string">&quot;text&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;content&quot;</span><span class="token operator">:</span><span class="token string">&quot;欢迎使用虹桥&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;description&quot;</span><span class="token operator">:</span><span class="token string">&quot;首页文案&quot;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>成功返回 HTTP 200、<code>code: 200</code>、<code>data: {config}</code>，正文与新标识属于同一次提交。即使内容相同，成功保存也会换新标识；<code>config.edit_revision</code> 是只读字段，不能替代顶层 <code>expected_edit_revision</code>。</p><table><thead><tr><th>HTTP</th><th>error_type</th><th>处理方式</th></tr></thead><tbody><tr><td>400</td><td>CONFIG_EDIT_REVISION_INVALID</td><td>缺失、空值或非标准小写 UUID v4；修正客户端请求</td></tr><tr><td>409</td><td>CONFIG_EDIT_CONFLICT</td><td>他人或导入迁移已修改；保留草稿，重新加载并核对</td></tr><tr><td>404</td><td>CONFIG_EDIT_TARGET_NOT_FOUND</td><td>配置已删除；保留草稿并刷新列表，不自动重建</td></tr></tbody></table><p>冲突正文为 <code>{code:409,msg:&quot;error&quot;,error:&quot;配置已被其他操作修改，请重新加载后核对再保存&quot;,error_type:&quot;CONFIG_EDIT_CONFLICT&quot;,resource_key:&quot;&lt;配置键&gt;&quot;}</code>，不附带最新正文或标识。认证和 CSRF 仍先执行；合法请求若范围已冻结，优先返回原有 <code>409 SCOPE_FROZEN</code>。</p><p>编辑窗口提供“复制我的草稿”“重新加载”“取消”。重新加载须确认替换未保存内容，取消或读取失败均保留草稿。网络中断导致保存结果未知时，保留草稿并重新加载核对，不自动重发或强制覆盖。</p><p>升级需同步切换前后端及管理客户端；旧客户端缺少顶层标识会收到真实 HTTP 400。启动时会持久化回填旧数据的空标识，不改变业务内容或时间戳；导入及迁移覆盖生成目标的新标识，跳过项不变。发布快照、版本摘要及版本运行态不包含此字段。不支持旧二进制与新二进制混合写同一数据库。</p><h2 id="_3-锁版和解锁" tabindex="-1"><a class="header-anchor" href="#_3-锁版和解锁">#</a> 3. 锁版和解锁</h2><table><thead><tr><th>方法与路径</th><th>参数</th><th>结果</th></tr></thead><tbody><tr><td>GET <code>/api/v1/freeze/status</code></td><td>查询 environment_key、pipeline_key</td><td>data 包含 state、revision、最后操作者/原因和时间、admin_configured</td></tr><tr><td>POST <code>/api/v1/freeze/lock</code></td><td>JSON：范围、expected_revision、选填 reason</td><td>locked，revision 递增</td></tr><tr><td>POST <code>/api/v1/freeze/unlock</code></td><td>同上</td><td>unlocked，revision 递增</td></tr><tr><td>GET <code>/api/v1/freeze/history</code></td><td>范围、limit、before_event_id</td><td>data.items、has_more、next_before_event_id</td></tr></tbody></table><p>revision 和事件 ID 使用十进制字符串；初始 revision 为 <code>&quot;0&quot;</code>。admin_configured 当前表示存在可用管理员账号，不再表示设置了旧密钥。历史 actor 为操作账号名，旧记录不回填。</p><p>先读状态，再提交读到的 revision：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_revision&quot;</span><span class="token operator">:</span><span class="token string">&quot;0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;reason&quot;</span><span class="token operator">:</span><span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>reason 可省略、空或全空格，服务端 trim 后保存空字符串；最多 500 个 Unicode 字符。锁定前检查引用资源的归属和存在性；失败返回 400 FREEZE_RESOURCE_PRECHECK_FAILED 及 resource_issues，原因包括 missing_metadata、file_missing、cross_scope_reference、unresolvable_reference。页面显示跨范围资源时，应核对或修复资源归属，不移除检查。</p><p>revision 过期返回 409 FREEZE_REVISION_CONFLICT，重复当前状态返回 409 FREEZE_STATE_UNCHANGED，响应提供 latest_state/latest_revision。不要自动拿新 revision 强行覆盖他人操作；刷新状态并由操作方确认。此接口没有 request_id 幂等机制。</p><p>范围被冻结的编辑区写入返回 409 SCOPE_FROZEN，并提供 blocked_scopes；写协调繁忙/超时返回 503 FREEZE_WRITE_GATE_BUSY / FREEZE_WRITE_TIMEOUT。</p><h2 id="_4-创建、切换和删除版本" tabindex="-1"><a class="header-anchor" href="#_4-创建、切换和删除版本">#</a> 4. 创建、切换和删除版本</h2><h3 id="管理读取" tabindex="-1"><a class="header-anchor" href="#管理读取">#</a> 管理读取</h3><table><thead><tr><th>方法与路径</th><th>查询参数</th><th>成功 data 结构</th></tr></thead><tbody><tr><td>GET <code>/api/v1/release/list</code></td><td>environment_key、pipeline_key、limit、before_id</td><td>items（每项 meta/is_active）、has_more、next_before_id、独立 active</td></tr><tr><td>GET <code>/api/v1/release/detail</code></td><td>environment_key、pipeline_key、version</td><td>meta、configs、assets、active</td></tr><tr><td>GET <code>/api/v1/release/active</code></td><td>environment_key、pipeline_key、可选 scope_id</td><td>active + 始终存在的 active_revision；未设置时 HTTP 200，active=null</td></tr><tr><td>GET <code>/api/v1/release/history</code></td><td>environment_key、pipeline_key、limit、before_event_id</td><td>items、has_more、next_before_event_id</td></tr></tbody></table><p>limit 缺省 20、最大 100；游标是接口返回的十进制字符串。版本列表按创建倒序，不显示逻辑删除项；active 独立于当前页，不应假设当前页必然包含生效版本。详情 configs 的 content 始终是字符串；assets/external_references 等空数组按实际显式 JSON 返回 <code>[]</code>。</p><p>meta 包含 snapshot_id、version、environment_key、pipeline_key、环境/渠道名、source_freeze_revision、creation_request_id、config_count、asset_count、asset_bytes、payload_sha256、manifest_sha256、external_references、reason、actor、created_at。active 包含 snapshot_id、version、revision、changed_at、changed_by、changed_reason。</p><h4 id="生效状态读取" tabindex="-1"><a class="header-anchor" href="#生效状态读取">#</a> 生效状态读取</h4><p><code>GET /api/v1/release/active</code> 的 <code>data</code> 始终包含：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span><span class="token property">&quot;active&quot;</span><span class="token operator">:</span> <span class="token null keyword">null</span><span class="token punctuation">,</span> <span class="token property">&quot;active_revision&quot;</span><span class="token operator">:</span> <span class="token string">&quot;0&quot;</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li><code>active_revision</code> 是字符串，不是数字、null 或空串；也不从 <code>last_version_number</code>、版本数量或事件数量推导。</li><li>有效范围没有 head 行时返回 <code>active:null</code> + <code>&quot;0&quot;</code>。</li><li>有效范围有 head、但 active 指针为空时，返回真实 head revision，允许 <code>&quot;7&quot;</code> 这类非零边界值；这是兼容边界状态，当前没有正常公开接口用于主动清空指针，不把它描述成日常操作。</li><li>有 active 时 <code>active_revision</code> 与 <code>active.revision</code> 完全相同；<code>active</code> 原字段保持不变，旧客户端继续可用。</li><li>超过 JS 安全整数的值仍按十进制原文返回；调用方不要转成 JS number。</li><li>查询只读同一份捕获状态，不创建 head、不写 revision 或审计；scope 错误、缺失/已删 active 版本等失败仍沿用原错误合同，不返回伪造的成功 null/0。</li><li>遇到 compare/activate revision 冲突时，重新调用本接口取得最新 <code>active_revision</code>，然后重新比较并由用户确认；不要把新 revision 自动用于切版，也不能从错误文字猜数字。</li></ul><h3 id="创建版本" tabindex="-1"><a class="header-anchor" href="#创建版本">#</a> 创建版本</h3><p><code>POST /api/v1/release/create</code>，管理会话和 CSRF：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_scope_id&quot;</span><span class="token operator">:</span><span class="token string">&quot;11111111-1111-4111-8111-111111111111&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_freeze_revision&quot;</span><span class="token operator">:</span><span class="token string">&quot;1&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;request_id&quot;</span><span class="token operator">:</span><span class="token string">&quot;41111111-2222-4333-8444-555555555555&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;reason&quot;</span><span class="token operator">:</span><span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>expected_freeze_revision 必须使用锁定后响应中的 revision，不能使用锁定前的值。新请求不提交 version：省略或空串都由后端在该 <code>(environment, pipeline)</code> scope 内自动分配 <code>v1</code>、<code>v2</code>……；非空 version 返回 400 <code>RELEASE_VERSION_AUTO_ASSIGNED</code>。auto 请求的 request_id 只绑定原始字段，重放返回同一 snapshot 和版本，不再消耗编号。历史手填版本的已提交 request_id 仍按原指纹确认并返回旧版本。创建不可变快照，但不会切换 active；成功 data 为 <code>{meta,replayed}</code>，前端必须使用 <code>meta.version</code> 的实际编号继续 compare/activate。</p><p>版本号按 scope 独立递增，删除版本或切回旧版不降低计数；旧名 <code>v1.0</code>、<code>test-1</code> 等原样保留且不参与自动序列。<code>config_release_head.last_version_number</code> 在启动时按所有历史规范版本（含已删）回填，迁移幂等。达到 int64 上限后返回 409 <code>RELEASE_VERSION_SEQUENCE_EXHAUSTED</code>，不会回绕。</p><p>源必须已锁定。发布检查会拒绝无法固定的嵌入媒体等资源问题，返回 409 RELEASE_RESOURCE_INVALID 和 resource_issues；普通超链接与嵌入媒体的规则不同，不能把提示的外部链接都理解为已复制进快照。当前不支持从 MinIO 源创建新快照，返回 503 RELEASE_STORAGE_UNSUPPORTED，不承诺真实多副本或远程存储部署已验证。</p><h3 id="切换生效-含切回" tabindex="-1"><a class="header-anchor" href="#切换生效-含切回">#</a> 切换生效（含切回）</h3><p><code>POST /api/v1/release/activate</code>：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;version&quot;</span><span class="token operator">:</span><span class="token string">&quot;v1.0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_active_revision&quot;</span><span class="token operator">:</span><span class="token string">&quot;0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;request_id&quot;</span><span class="token operator">:</span><span class="token string">&quot;51111111-2222-4333-8444-555555555555&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;reason&quot;</span><span class="token operator">:</span><span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>先读取 active，尚未生效时使用 <code>&quot;0&quot;</code>；已有 active 时使用其 revision。只移动生效指针，不修改编辑区或版本内容。成功 data 为 operation、active、version；operation 包含 request_id、replayed、applied_revision。active 表示响应时的当前状态，重放旧请求不保证它仍是当时切换的版本。</p><p>并发 revision 不符返回 409 RELEASE_ACTIVE_REVISION_CONFLICT，可能带 latest_active；目标已生效返回 409 RELEASE_ACTIVE_UNCHANGED。应刷新并确认，不在后台盲目覆盖。</p><h3 id="删除非生效版本" tabindex="-1"><a class="header-anchor" href="#删除非生效版本">#</a> 删除非生效版本</h3><p><code>POST /api/v1/release/delete</code>：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span><span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;version&quot;</span><span class="token operator">:</span><span class="token string">&quot;v0.9&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_snapshot_id&quot;</span><span class="token operator">:</span><span class="token string">&quot;61111111-2222-4333-8444-555555555555&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;request_id&quot;</span><span class="token operator">:</span><span class="token string">&quot;71111111-2222-4333-8444-555555555555&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;reason&quot;</span><span class="token operator">:</span><span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>成功 data 包含 request_id、snapshot_id、version、deleted、deleted_at、deleted_by、reason、replayed。只允许逻辑删除非 active 版本，删除 active 返回 409 RELEASE_DELETE_ACTIVE；snapshot 不匹配返回 409 RELEASE_SNAPSHOT_MISMATCH。</p><p>删除后列表隐藏、历史保留，版本号不能再次使用，详情/运行时/静态导出/资源的新访问返回 410 RELEASE_VERSION_DELETED。文件保留，不回收空间，也没有恢复接口。已开始且固定了目标的读取/导出允许完成，已下载的副本不会被撤回。有历史版本（含删除记录）的范围仍不能删除环境/渠道，返回 409 RELEASE_SCOPE_HAS_VERSIONS。</p><h3 id="原因、幂等和超时确认" tabindex="-1"><a class="header-anchor" href="#原因、幂等和超时确认">#</a> 原因、幂等和超时确认</h3><p>创建、切换、删除的 reason 与锁版相同：选填、trim、最多 500 个 Unicode 字符。request_id 必须是 UUID；同一次操作结果不确定时保留整份首次 payload，用同一 ID 原样确认。改变范围、目标、原因或 revision 等字段就是新操作，应使用新 ID。同一操作内 ID 重用但字段不同返回 409 RELEASE_REQUEST_CONFLICT。</p><p>创建重放在版本后来被删除后返回 410；切换重放确认历史操作而不重新切回；删除相同请求可重放原删除结果。不要把“网络超时”理解成“服务端一定没执行”，也不要为了重试改掉已提交的字段。</p><h2 id="_5-推荐调用顺序" tabindex="-1"><a class="header-anchor" href="#_5-推荐调用顺序">#</a> 5. 推荐调用顺序</h2><ol><li>登录并保存会话内 CSRF；管理接口统一走 Cookie。</li><li>编辑配置并核对资源范围。</li><li>读取 freeze/status，带 expected_revision 锁版，取得新 revision。</li><li>带锁版 revision 创建版本，保存返回的 version/snapshot_id。</li><li>读取 release/active，带 expected_active_revision 切换。</li><li>通过公开 runtime/release 核对生效结果；需要固定资源包时使用读取返回的版本和 snapshot_id。</li><li>下一轮编辑前按最新 revision 解锁；清理版本时只删除非 active 版本。</li></ol><p>认证失效回到登录，不恢复旧 Bearer 兜底；409 需核对最新状态，参数错误不盲目重试。只读列表可正常刷新，不应因刷新产生新的锁版或发布副作用。</p>`,73)])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};